import React, { useState, useEffect } from 'react';

import { Link } from 'react-router-dom';

import { getFeaturedProducts, getProductCategories } from '../services/api';

import { isAuthenticated } from '../util/auth';

import ProductCard from '../components/ProductCard';

import Toast from '../components/Toast';

import { useTheme } from '../context/ThemeContext';

import useToast from '../hooks/useToast';



const Home = () => {

  const [featuredProducts, setFeaturedProducts] = useState([]);

  const [categories, setCategories] = useState([]);

  const [loading, setLoading] = useState(true);

  const [currentSlide, setCurrentSlide] = useState(0);

  const [featureSlide, setFeatureSlide] = useState(0);

  const { isDarkMode } = useTheme();

  const { toasts, removeToast } = useToast();



  useEffect(() => {

    fetchData();

    

    // Auto-rotate hero slides

    const heroInterval = setInterval(() => {

      setCurrentSlide((prev) => (prev + 1) % 3);

    }, 4000);

    

    // Auto-rotate feature slides

    const featureInterval = setInterval(() => {

      setFeatureSlide((prev) => (prev + 1) % 3);

    }, 3000);

    

    return () => {

      clearInterval(heroInterval);

      clearInterval(featureInterval);

    };

  }, []);



  const fetchData = async () => {

    try {

      setLoading(true);

      const [featuredRes, categoriesRes] = await Promise.all([

        getFeaturedProducts(),

        getProductCategories()

      ]);

      setFeaturedProducts(featuredRes.data);

      setCategories(categoriesRes.data);

    } catch (error) {

      console.error('Error fetching data:', error);

} finally {

      setLoading(false);

    }

  };



  const userAuthenticated = isAuthenticated();



  return (

    <div className="fade-in">

      {/* Animated Hero Section */}

      <section className="relative min-h-screen flex items-center justify-center overflow-hidden rounded-2xl mb-12">

        {/* Animated Background */}

        <div className="absolute inset-0 bg-gradient-to-br from-blue-600 via-purple-600 to-pink-600">

          <div className="absolute inset-0 bg-black/20"></div>

          

          {/* Floating Product Images */}

          <div className="absolute inset-0">

            <div className="absolute top-10 left-10 w-20 h-20 bg-white/10 backdrop-blur-lg rounded-full flex items-center justify-center animate-float">

              <span className="text-4xl">🥛</span>

            </div>

            <div className="absolute top-20 right-20 w-16 h-16 bg-white/10 backdrop-blur-lg rounded-full flex items-center justify-center animate-float animation-delay-2">

              <span className="text-3xl">🧀</span>

            </div>

            <div className="absolute bottom-20 left-20 w-24 h-24 bg-white/10 backdrop-blur-lg rounded-full flex items-center justify-center animate-float animation-delay-4">

              <span className="text-5xl">🧈</span>

            </div>

            <div className="absolute bottom-10 right-10 w-18 h-18 bg-white/10 backdrop-blur-lg rounded-full flex items-center justify-center animate-float animation-delay-6">

              <span className="text-4xl">🍯</span>

            </div>

            <div className="absolute top-1/2 left-1/3 w-20 h-20 bg-white/10 backdrop-blur-lg rounded-full flex items-center justify-center animate-float animation-delay-8">

              <span className="text-4xl">🍦</span>

            </div>

          </div>

          

          {/* Animated Gradient Overlay */}

          <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-transparent to-transparent"></div>

        </div>



        {/* Hero Content */}

        <div className="relative z-10 text-center px-4 max-w-6xl mx-auto">

          

          {/* Animated Milk Bottle Logo */}

          <div className="mb-8">

            <div className="inline-block relative">

              <div className="w-24 h-24 relative animate-bounce">

                {/* Glow Effect */}

                <div className="absolute inset-0 bg-white/30 backdrop-blur-xl rounded-3xl animate-pulse"></div>

                

                {/* Main Bottle */}

                <div className="absolute inset-0 bg-white/90 backdrop-blur-xl rounded-3xl flex items-center justify-center transform hover:scale-110 transition-transform duration-500 shadow-2xl">

                  <svg className="w-16 h-16 text-blue-600" fill="currentColor" viewBox="0 0 24 24">

                    <path d="M7 2v2h1v14a4 4 0 004 4h0a4 4 0 004-4V4h1V2H7zm2 2h6v14a2 2 0 01-2 2h0a2 2 0 01-2-2V4z"/>

                    <path d="M9 6h6v2H9z" opacity="0.3"/>

                  </svg>

                </div>

                

                {/* Animated Milk Drops */}

                <div className="absolute -top-2 -right-2 w-4 h-4 bg-blue-400 rounded-full animate-bounce">

                  <div className="w-full h-full bg-blue-500 rounded-full animate-ping"></div>

                </div>

                <div className="absolute -bottom-1 -left-1 w-3 h-3 bg-purple-400 rounded-full animate-pulse"></div>

              </div>

            </div>

          </div>



          {/* Auto-Sliding Text */}

          <div className="mb-8 h-24 overflow-hidden">

            <div className="transition-transform duration-500 ease-in-out" style={{ transform: `translateY(-${currentSlide * 96}px)` }}>

              <div className="h-24 flex items-center justify-center">

                <h1 className="text-4xl md:text-6xl font-bold text-white">

                  Fresh Milk & Dairy Products

                </h1>

              </div>

              <div className="h-24 flex items-center justify-center">

                <h1 className="text-4xl md:text-6xl font-bold text-white">

                  Farm Fresh Quality

                </h1>

              </div>

              <div className="h-24 flex items-center justify-center">

                <h1 className="text-4xl md:text-6xl font-bold text-white">

                  Delivered Daily

                </h1>

              </div>

            </div>

          </div>

          

          <div className="mb-8">

            <p className="text-xl md:text-2xl text-white/90 max-w-2xl mx-auto animate-fade-in">

              Delivering farm-fresh dairy products directly to your doorstep

            </p>

          </div>



          <div className="flex flex-col sm:flex-row gap-4 justify-center mb-12">

            <Link 

              to="/products" 

              className="px-8 py-4 bg-white text-blue-600 rounded-full font-bold text-lg hover:bg-blue-50 transform hover:scale-105 transition-all duration-300 shadow-2xl animate-fade-in animation-delay-2"

            >

              Shop Now

            </Link>

            {!userAuthenticated && (

              <Link 

                to="/register" 

                className="px-8 py-4 border-2 border-white text-white rounded-full font-bold text-lg hover:bg-white hover:text-blue-600 transform hover:scale-105 transition-all duration-300 animate-fade-in animation-delay-4"

              >

                Create Account

              </Link>

            )}

          </div>



          {/* Slide Indicators */}

          <div className="flex justify-center space-x-2">

            {[0, 1, 2].map((index) => (

              <button

                key={index}

                onClick={() => setCurrentSlide(index)}

                className={`w-3 h-3 rounded-full transition-all duration-300 ${

                  currentSlide === index 

                    ? 'bg-white w-8' 

                    : 'bg-white/50 hover:bg-white/70'

                }`}

              />

            ))}

          </div>

        </div>

      </section>



      {/* Modern Categories Section */}

      <section className="mb-16 relative">

        {/* Modern Section Header */}

        <div className="text-center mb-12">

          <div className="inline-block relative group">

            <h2 className={`text-4xl md:text-5xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

              <span className="bg-gradient-to-r from-primary-600 via-secondary-600 to-primary-600 bg-clip-text text-transparent">

                Shop by Category

              </span>

            </h2>

            {/* Animated Underline - Like Featured Products */}

            <div className="absolute -bottom-2 left-0 w-full h-1 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-full transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500"></div>

          </div>

          <p className={`text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} mt-4 max-w-2xl mx-auto`}>

            Explore our wide range of fresh dairy products

          </p>

        </div>



        {/* Modern Grid Layout */}

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-8">

          {categories.map((category) => (

            <Link

              key={category}

              to={`/products?category=${category}`}

              className="group relative block"

            >

              {/* Ultra-Premium Card Container */}

              <div className="relative p-10 text-center bg-gradient-to-br from-white via-gray-50 to-gray-100 dark:from-gray-800 dark:via-gray-900 dark:to-black rounded-[3rem] border-2 border-gray-200/50 dark:border-gray-700/50 hover:border-primary-500 transition-all duration-1000 transform hover:scale-105 hover:shadow-4xl hover:shadow-primary-500/20 overflow-hidden group">

                

                {/* Multi-Layer Animated Background */}

                <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-all duration-1000">

                  {/* Base Gradient */}

                  <div className="absolute inset-0 bg-gradient-to-br from-primary-500/10 via-transparent to-secondary-500/10 animate-gradient-shift"></div>

                  

                  {/* Sliding Light Effect */}

                  <div className="absolute inset-0">

                    <div className="absolute top-0 left-0 w-full h-1/3 bg-gradient-to-r from-transparent via-white/20 to-transparent animate-slide"></div>

                    <div className="absolute top-1/3 left-0 w-full h-1/3 bg-gradient-to-r from-transparent via-primary-200/20 to-transparent animate-slide animation-delay-2"></div>

                    <div className="absolute bottom-0 left-0 w-full h-1/3 bg-gradient-to-r from-transparent via-secondary-200/20 to-transparent animate-slide animation-delay-4"></div>

                  </div>

                  

                                  </div>

                

                {/* Luxury Glow Effect */}

                <div className="absolute inset-0 bg-gradient-to-br from-primary-500/20 via-secondary-500/15 to-primary-500/20 rounded-[3rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-3xl"></div>

                

                {/* Glass Morphism Overlay */}

                <div className="absolute inset-0 bg-gradient-to-tr from-white/10 to-transparent backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-all duration-1000"></div>

                

                {/* Icon Container with Ultra-Advanced Effects */}

                <div className="relative z-10 mb-8">

                  <div className="w-24 h-24 mx-auto relative">

                    {/* Multi-Layer Icon Background */}

                    <div className="absolute inset-0 bg-gradient-to-br from-primary-100 via-white to-secondary-100 dark:from-primary-900 dark:via-gray-800 dark:to-secondary-900 rounded-[2.5rem] flex items-center justify-center transform transition-all duration-1000 group-hover:scale-125 group-hover:rotate-12 shadow-2xl border-2 border-white/50 dark:border-gray-700/50">

                      {/* Inner Glow */}

                      <div className="absolute inset-2 bg-gradient-to-br from-white/50 to-transparent rounded-[2rem]"></div>

                      

                      {/* Icon with Advanced Effects */}

                      <span className="text-5xl transform transition-all duration-700 group-hover:scale-150 group-hover:rotate-180 drop-shadow-2xl relative z-10">

                        {category === 'milk' && '🥛'}

                        {category === 'butter' && '🧈'}

                        {category === 'buttermilk' && '🫙'}

                        {category === 'cheese' && '🧀'}

                        {category === 'cream' && '🍦'}

                        {category === 'curd' && '🥣'}

                        {category === 'ghee' && '🍯'}

                        {category === 'lassi' && '🥤'}

                        {category === 'paneer' && '🧊'}

                        {category === 'yogurt' && '🍶'}

                      </span>

                    </div>

                    

                    {/* Ultra-Advanced Icon Glow */}

                    <div className="absolute inset-0 bg-gradient-to-br from-primary-400/60 via-secondary-400/40 to-primary-400/60 rounded-[2.5rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-2xl"></div>

                    

                                      </div>

                </div>

                

                {/* Ultra-Enhanced Category Name */}

                <div className="relative z-10">

                  <h3 className={`font-black text-2xl capitalize transition-all duration-700 ${isDarkMode ? 'text-white group-hover:text-primary-300' : 'text-gray-800 group-hover:text-primary-600'}`}>

                    {category}

                  </h3>

                  <div className="mt-3 h-1 bg-gradient-to-r from-transparent via-primary-500 to-transparent transform scale-x-0 group-hover:scale-x-100 transition-all duration-700 rounded-full"></div>

                  <div className="mt-2 text-sm font-medium opacity-0 group-hover:opacity-100 transition-opacity duration-700 text-primary-600 dark:text-primary-400">

                    Explore Products →

                  </div>

                </div>

                

                                

                {/* Premium Card Edge Effects */}

                <div className="absolute inset-0 rounded-[3rem] border-2 border-transparent group-hover:border-primary-300/50 transition-all duration-1000"></div>

                <div className="absolute inset-1 rounded-[3rem] border border-transparent group-hover:border-white/30 transition-all duration-1000"></div>

                

                {/* Hover Reveal Effect */}

                <div className="absolute inset-x-0 bottom-0 h-1/3 bg-gradient-to-t from-primary-500/10 to-transparent opacity-0 group-hover:opacity-100 transition-all duration-1000 transform translate-y-full group-hover:translate-y-0"></div>

              </div>

            </Link>

          ))}

        </div>

      </section>



      {/* Modern Featured Products Section */}

      <section className="mb-16">

        {/* Modern Section Header */}

        <div className="text-center mb-12">

          <div className="inline-block relative group">

            <h2 className={`text-4xl md:text-5xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

              <span className="bg-gradient-to-r from-primary-600 via-secondary-600 to-primary-600 bg-clip-text text-transparent">

                Featured Products

              </span>

            </h2>

            {/* Underline Animation */}

            <div className="absolute -bottom-2 left-0 w-full h-1 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-full transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500"></div>

          </div>

          <p className={`text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} mt-4 max-w-2xl mx-auto`}>

            Discover our handpicked selection of premium dairy products

          </p>

        </div>

        

        {loading ? (

          <div className="flex justify-center py-16">

            <div className="relative">

              <div className="w-16 h-16 border-4 border-primary-200 border-t-primary-600 rounded-full animate-spin"></div>

              <div className="absolute inset-0 flex items-center justify-center">

                <div className="w-8 h-8 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-full animate-pulse"></div>

              </div>

            </div>

          </div>

        ) : featuredProducts.length > 0 ? (

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">

            {featuredProducts.slice(0, 12).map((product, index) => (

              <ProductCard key={product._id} product={product} index={index} />

            ))}

          </div>

        ) : (

          <div className="text-center py-16">

            <div className="inline-block relative mb-8">

              <div className="w-32 h-32 bg-gradient-to-br from-primary-100 to-secondary-100 dark:from-primary-900 dark:to-secondary-900 rounded-[3rem] flex items-center justify-center mx-auto">

                <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-primary-600 dark:text-primary-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">

                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" />

                </svg>

              </div>

              {/* Empty State Glow */}

              <div className="absolute inset-0 bg-gradient-to-br from-primary-500/20 to-secondary-500/20 rounded-[3rem] blur-2xl animate-pulse"></div>

            </div>

            <h3 className={`text-3xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

              No products yet

            </h3>

            <p className={`text-lg mb-8 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} max-w-md mx-auto`}>

              Check back soon for fresh dairy products!

            </p>

            <Link 

              to="/products" 

              className="inline-flex items-center px-8 py-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-bold rounded-2xl hover:from-primary-600 hover:to-secondary-600 transform transition-all duration-300 hover:scale-105 shadow-xl"

            >

              Browse Products

              <svg className="w-5 h-5 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">

                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />

              </svg>

            </Link>

          </div>

        )}

        

        {/* View All Products Section */}

        <div className={`text-center mt-16 p-8 rounded-3xl ${isDarkMode ? 'bg-gray-800/50 backdrop-blur-xl border border-white/10' : 'bg-white/70 backdrop-blur-xl border border-gray-200'} shadow-xl`}>

          <div className="max-w-2xl mx-auto">

            <h3 className={`text-2xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

              🛒 Explore Our Complete Collection

            </h3>

            <p className={`text-lg mb-6 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>

              Discover all 55+ premium dairy products including milk, ghee, paneer, cheese, butter, curd, yogurt, lassi, and more!

            </p>

            <div className="flex flex-col sm:flex-row gap-4 justify-center">

              <Link 

                to="/products" 

                className="inline-flex items-center px-8 py-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-bold rounded-2xl hover:from-primary-600 hover:to-secondary-600 transform transition-all duration-300 hover:scale-105 shadow-xl"

              >

                🛍️ View All Products

                <svg className="w-5 h-5 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">

                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 8l4 4m0 0l-4 4m4-4H3" />

                </svg>

              </Link>

              <Link 

                to="/products?category=milk" 

                className="inline-flex items-center px-8 py-4 border-2 border-primary-500 text-primary-600 dark:text-primary-400 font-bold rounded-2xl hover:bg-primary-500 hover:text-white transform transition-all duration-300 hover:scale-105"

              >

                🥛 Browse Milk Products

              </Link>

            </div>

          </div>

        </div>



              </section>



      {/* Modern Features Section */}

      <section className="mb-16">

        {/* Section Header */}

        <div className="text-center mb-12">

          <div className="inline-block relative group">

            <h2 className={`text-4xl md:text-5xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

              <span className="bg-gradient-to-r from-primary-600 via-secondary-600 to-primary-600 bg-clip-text text-transparent">

                Why Choose Us

              </span>

            </h2>

            <div className="absolute -bottom-2 left-0 w-full h-1 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-full transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500"></div>

          </div>

          <p className={`text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} mt-4 max-w-2xl mx-auto`}>

            We deliver excellence in every drop of milk

          </p>

        </div>



        {/* Modern Features Carousel - Enhanced Visual Experience */}

        <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-gray-50 via-white to-gray-100 dark:from-gray-900 dark:via-gray-800 dark:to-gray-900 shadow-2xl">
          
          {/* Animated Background Elements */}

          <div className="absolute inset-0 overflow-hidden">
            <div className="absolute top-10 left-10 w-32 h-32 bg-gradient-to-br from-primary-500/20 to-secondary-500/20 rounded-full blur-3xl animate-pulse"></div>
            <div className="absolute bottom-10 right-10 w-40 h-40 bg-gradient-to-br from-secondary-500/20 to-primary-500/20 rounded-full blur-3xl animate-pulse animation-delay-2"></div>
            <div className="absolute top-1/2 left-1/3 w-24 h-24 bg-gradient-to-br from-blue-500/15 to-purple-500/15 rounded-full blur-2xl animate-pulse animation-delay-4"></div>
            <div className="absolute bottom-1/3 right-1/4 w-28 h-28 bg-gradient-to-br from-pink-500/15 to-orange-500/15 rounded-full blur-2xl animate-pulse animation-delay-6"></div>
          </div>

          {/* Gradient Overlay */}

          <div className="absolute inset-0 bg-gradient-to-r from-primary-500/5 via-transparent to-secondary-500/5"></div>

          <div className="relative h-80 md:h-96">
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="relative w-full max-w-6xl">
                {/* Feature Cards with Modern Sliding Animation */}

                <div className="flex justify-center items-center" style={{ perspective: '1500px' }}>
                  <div 
                    className="relative w-full h-80 md:h-96 transition-all duration-1200 ease-[cubic-bezier(0.4,0,0.2,1)]"
                    style={{ transformStyle: 'preserve-3d' }}
                  >
                    {/* Fresh Quality Card */}
                    <div 
                      className={`absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 transition-all duration-1000 ease-[cubic-bezier(0.4,0,0.2,1)] ${
                        featureSlide === 0 
                          ? 'opacity-100 scale-105 z-30 translate-x-0' 
                          : featureSlide === 1 
                            ? 'opacity-0 scale-75 translate-x-full rotate-y-30 z-10'
                            : 'opacity-0 scale-50 -translate-x-full -rotate-y-30 z-0'
                      }`}
                      style={{ 
                        transformStyle: 'preserve-3d',
                        transform: featureSlide === 0 
                          ? 'translate(-50%, -50%) translateX(0) rotateY(0deg) translateZ(0px)' 
                          : featureSlide === 1 
                            ? 'translate(-50%, -50%) translateX(300%) rotateY(35deg) translateZ(-50px)' 
                            : 'translate(-50%, -50%) translateX(-300%) rotateY(-35deg) translateZ(-50px)'
                      }}
                    >
                      <div className="group relative overflow-hidden transition-all duration-800 ease-[cubic-bezier(0.4,0,0.2,1)] hover:shadow-4xl hover:shadow-primary-500/20 transform hover:scale-110 rounded-[2.5rem] border-2 border-gray-200/50 dark:border-gray-700/50 hover:border-primary-500/50 bg-gradient-to-br from-white via-gray-50 to-gray-100 dark:from-gray-800 dark:via-gray-900 dark:to-black p-8 text-center w-80 mx-auto">
                        {/* Animated Icon Container */}
                        <div className="relative w-20 h-20 mx-auto mb-6">
                          <div className="absolute inset-0 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-[2rem] transform rotate-6 group-hover:rotate-12 transition-transform duration-800 ease-[cubic-bezier(0.4,0,0.2,1)]"></div>

                          <div className="absolute inset-0 bg-gradient-to-br from-primary-400 to-secondary-400 rounded-[2rem] flex items-center justify-center transform group-hover:scale-110 transition-transform duration-500 ease-[cubic-bezier(0.4,0,0.2,1)]">

                            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">

                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />

                            </svg>

                          </div>

                          {/* Glow Effect */}

                          <div className="absolute inset-0 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-[2rem] blur-xl opacity-50 group-hover:opacity-100 transition-opacity duration-700"></div>

                        </div>

                        

                        <h3 className={`text-2xl font-bold mb-3 transition-all duration-300 group-hover:text-primary-600 dark:group-hover:text-primary-400 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

                          Fresh Quality

                        </h3>

                        <p className={`text-base transition-all duration-300 group-hover:text-gray-700 dark:group-hover:text-gray-300 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>

                          100% pure and fresh dairy products sourced from trusted farms

                        </p>

                        

                        {/* Card Edge Effects */}

                        <div className="absolute inset-0 rounded-[2.5rem] border-2 border-transparent group-hover:border-primary-300/50 transition-all duration-1000 pointer-events-none"></div>

                        <div className="absolute inset-0 bg-gradient-to-br from-primary-500/10 via-secondary-500/10 to-primary-500/10 rounded-[2.5rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-xl pointer-events-none"></div>

                      </div>

                    </div>



                    {/* Fast Delivery Card */}
                    <div 
                      className={`absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 transition-all duration-1000 ease-[cubic-bezier(0.4,0,0.2,1)] ${
                        featureSlide === 1 
                          ? 'opacity-100 scale-105 z-30 translate-x-0' 
                          : featureSlide === 2 
                            ? 'opacity-0 scale-75 translate-x-full rotate-y-30 z-10'
                            : 'opacity-0 scale-50 -translate-x-full -rotate-y-30 z-0'
                      }`}
                      style={{ 
                        transformStyle: 'preserve-3d',
                        transform: featureSlide === 1 
                          ? 'translate(-50%, -50%) translateX(0) rotateY(0deg) translateZ(0px)' 
                          : featureSlide === 2 
                            ? 'translate(-50%, -50%) translateX(300%) rotateY(35deg) translateZ(-50px)' 
                            : 'translate(-50%, -50%) translateX(-300%) rotateY(-35deg) translateZ(-50px)'
                      }}
                    >
                      <div className="group relative overflow-hidden transition-all duration-800 ease-[cubic-bezier(0.4,0,0.2,1)] hover:shadow-4xl hover:shadow-primary-500/20 transform hover:scale-110 rounded-[2.5rem] border-2 border-gray-200/50 dark:border-gray-700/50 hover:border-primary-500/50 bg-gradient-to-br from-white via-gray-50 to-gray-100 dark:from-gray-800 dark:via-gray-900 dark:to-black p-8 text-center w-80 mx-auto">
                        {/* Animated Icon Container */}
                        <div className="relative w-20 h-20 mx-auto mb-6">
                          <div className="absolute inset-0 bg-gradient-to-br from-secondary-500 to-primary-500 rounded-[2rem] transform -rotate-6 group-hover:-rotate-12 transition-transform duration-800 ease-[cubic-bezier(0.4,0,0.2,1)] z-0"></div>
                          <div className="absolute inset-0 bg-gradient-to-br from-secondary-400 to-primary-400 rounded-[2rem] flex items-center justify-center transform group-hover:scale-110 transition-transform duration-600 ease-[cubic-bezier(0.4,0,0.2,1)] z-10 shadow-lg">

                            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white drop-shadow-md" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>

                              <path strokeLinecap="round" strokeLinejoin="round" d="M13 10V3L4 14h7v7l9-11h-7z" />

                            </svg>

                          </div>

                          <div className="absolute inset-0 bg-gradient-to-br from-secondary-500 to-primary-500 rounded-[2rem] blur-xl opacity-50 group-hover:opacity-100 transition-opacity duration-700 z-0"></div>

                        </div>

                        

                        <h3 className={`text-2xl font-bold mb-3 transition-all duration-300 group-hover:text-primary-600 dark:group-hover:text-primary-400 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

                          Fast Delivery

                        </h3>

                        <p className={`text-base transition-all duration-300 group-hover:text-gray-700 dark:group-hover:text-gray-300 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>

                          Quick and reliable delivery to ensure product freshness

                        </p>

                        

                        <div className="absolute inset-0 rounded-[2.5rem] border-2 border-transparent group-hover:border-primary-300/50 transition-all duration-1000 pointer-events-none"></div>

                        <div className="absolute inset-0 bg-gradient-to-br from-secondary-500/10 via-primary-500/10 to-secondary-500/10 rounded-[2.5rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-xl pointer-events-none"></div>

                      </div>

                    </div>



                    {/* Best Price Card */}
                    <div 
                      className={`absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 transition-all duration-1200 ease-[cubic-bezier(0.4,0,0.2,1)] ${
                        featureSlide === 2 
                          ? 'opacity-100 scale-105 z-30 translate-x-0' 
                          : featureSlide === 0 
                            ? 'opacity-0 scale-75 translate-x-full rotate-y-30 z-10'
                            : 'opacity-0 scale-50 -translate-x-full -rotate-y-30 z-0'
                      }`}
                      style={{ 
                        transformStyle: 'preserve-3d',
                        transform: featureSlide === 2 
                          ? 'translate(-50%, -50%) translateX(0) rotateY(0deg) translateZ(0px)' 
                          : featureSlide === 0 
                            ? 'translate(-50%, -50%) translateX(300%) rotateY(35deg) translateZ(-50px)' 
                            : 'translate(-50%, -50%) translateX(-300%) rotateY(-35deg) translateZ(-50px)'
                      }}
                    >

                      <div className="group relative overflow-hidden transition-all duration-900 ease-[cubic-bezier(0.4,0,0.2,1)] hover:shadow-4xl hover:shadow-primary-500/20 transform hover:scale-110 rounded-[2.5rem] border-2 border-gray-200/50 dark:border-gray-700/50 hover:border-primary-500/50 bg-gradient-to-br from-white via-gray-50 to-gray-100 dark:from-gray-800 dark:via-gray-900 dark:to-black p-8 text-center w-80 mx-auto">

                        {/* Animated Icon Container */}

                        <div className="relative w-20 h-20 mx-auto mb-6">

                          <div className="absolute inset-0 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-[2rem] transform rotate-3 group-hover:rotate-6 transition-transform duration-900 ease-[cubic-bezier(0.4,0,0.2,1)]"></div>

                          <div className="absolute inset-0 bg-gradient-to-br from-primary-400 to-secondary-400 rounded-[2rem] flex items-center justify-center transform group-hover:scale-110 transition-transform duration-600 ease-[cubic-bezier(0.4,0,0.2,1)]">

                            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">

                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />

                            </svg>

                          </div>

                          <div className="absolute inset-0 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-[2rem] blur-xl opacity-50 group-hover:opacity-100 transition-opacity duration-700"></div>

                        </div>

                        

                        <h3 className={`text-2xl font-bold mb-3 transition-all duration-300 group-hover:text-primary-600 dark:group-hover:text-primary-400 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>

                          Best Price

                        </h3>

                        <p className={`text-base transition-all duration-300 group-hover:text-gray-700 dark:group-hover:text-gray-300 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>

                          Competitive prices for premium quality dairy products

                        </p>

                        

                        <div className="absolute inset-0 rounded-[2.5rem] border-2 border-transparent group-hover:border-primary-300/50 transition-all duration-1000 pointer-events-none"></div>

                        <div className="absolute inset-0 bg-gradient-to-br from-primary-500/10 via-secondary-500/10 to-primary-500/10 rounded-[2.5rem] opacity-0 group-hover:opacity-100 transition-all duration-1000 blur-xl pointer-events-none"></div>

                      </div>

                    </div>

                  </div>

                </div>

              </div>

            </div>

          </div>



          {/* Modern Navigation Dots */}
          <div className="flex justify-center items-center space-x-6 mt-10">
            {[0, 1, 2].map((index) => (
              <button
                key={index}
                onClick={() => setFeatureSlide(index)}
                className={`relative group transition-all duration-600 ease-[cubic-bezier(0.4,0,0.2,1)] ${
                  featureSlide === index 
                    ? 'transform scale-125' 
                    : 'hover:scale-110'
                }`}
              >
                {/* Glow Background */}
                <div className={`absolute inset-0 rounded-full transition-all duration-600 ease-[cubic-bezier(0.4,0,0.2,1)] ${
                  featureSlide === index 
                    ? 'bg-gradient-to-r from-primary-500 to-secondary-500 opacity-30 blur-xl scale-150' 
                    : 'bg-gray-400 opacity-0 group-hover:opacity-20 blur-lg scale-125'
                }`}></div>
                
                {/* Main Dot */}
                <div className={`relative w-4 h-4 rounded-full transition-all duration-600 ease-[cubic-bezier(0.4,0,0.2,1)] ${
                  featureSlide === index 
                    ? 'bg-gradient-to-r from-primary-500 to-secondary-500 shadow-lg shadow-primary-500/50' 
                    : 'bg-gray-300 dark:bg-gray-600 hover:bg-gray-400 dark:hover:bg-gray-500'
                }`}>
                  {/* Active Ping Animation */}
                  {featureSlide === index && (
                    <div className="absolute inset-0 rounded-full bg-white/40 animate-ping"></div>
                  )}
                </div>
                
                {/* Label */}
                <div className={`absolute -bottom-8 left-1/2 transform -translate-x-1/2 text-xs font-semibold transition-all duration-400 ease-[cubic-bezier(0.4,0,0.2,1)] whitespace-nowrap ${
                  featureSlide === index 
                    ? 'opacity-100 text-primary-600 dark:text-primary-400' 
                    : 'opacity-0 group-hover:opacity-70 text-gray-500 dark:text-gray-400'
                }`}>
                  {index === 0 ? 'Quality' : index === 1 ? 'Delivery' : 'Price'}
                </div>
              </button>
            ))}
          </div>

          {/* Progress Indicator */}
          <div className="flex justify-center mt-8">
            <div className={`inline-flex items-center gap-3 px-6 py-3 rounded-full transition-all duration-400 ease-[cubic-bezier(0.4,0,0.2,1)] ${
              isDarkMode ? 'bg-gray-800/60 border border-gray-700/50' : 'bg-white/60 border border-gray-200/50'
            } backdrop-blur-md shadow-lg`}>
              <span className={`text-sm font-medium ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                Features
              </span>
              <div className="flex gap-1.5">
                {[0, 1, 2].map((i) => (
                  <div 
                    key={i}
                    className={`h-1.5 rounded-full transition-all duration-600 ease-[cubic-bezier(0.4,0,0.2,1)] ${
                      i === featureSlide 
                        ? 'bg-gradient-to-r from-primary-500 to-secondary-500 w-6' 
                        : 'bg-gray-300 dark:bg-gray-600 w-1.5'
                    }`}
                  ></div>
                ))}
              </div>
            </div>
          </div>

        </div>

      </section>



      {/* Toast Container */}

      {toasts.map(toast => (

        <Toast

          key={toast.id}

          message={toast.message}

          type={toast.type}

          duration={toast.duration}

          onClose={() => removeToast(toast.id)}

        />

      ))}

    </div>

  );

};



export default Home;
